DO $tag$
DECLARE
  r record;
BEGIN
  FOR r IN
    SELECT n.nspname AS schema_name, c.relname AS table_name, a.attname AS column_name, c.oid AS rel_oid, a.attnum,
           CASE
             WHEN p.column_name IS NULL THEN 'platform-migration:declared_defaults'
             WHEN p.has_default = false AND a.atthasdef THEN 'platform-migration:declared_defaults:default'
             WHEN p.nullable = false AND NOT a.attnotnull THEN 'platform-migration:declared_defaults:relax'
           END AS tag
      FROM pg_attribute a
      JOIN pg_class c ON c.oid = a.attrelid
      JOIN pg_namespace n ON n.oid = c.relnamespace
      LEFT JOIN platform_convergence_pre p ON p.schema_name = n.nspname AND p.table_name = c.relname AND p.column_name = a.attname
     WHERE (n.nspname, c.relname) IN (VALUES ('public', 'claim_updates'), ('public', 'claims'), ('public', 'grievances'), ('public', 'mission_audits'), ('public', 'organization_members'), ('public', 'organizations')) AND a.attnum > 0 AND NOT a.attisdropped
  LOOP
    IF r.tag IS NOT NULL AND col_description(r.rel_oid, r.attnum) IS NULL THEN
      EXECUTE format('COMMENT ON COLUMN %I.%I.%I IS %L', r.schema_name, r.table_name, r.column_name, r.tag);
    END IF;
  END LOOP;
END
